# expense_record_store.py\n# [LATER-STEP] Persist normalized expense records in a managed document store\n\nimport os\nfrom google.cloud import firestore\nfrom google.auth.exceptions import GoogleAuthError\nfrom document_models import NormalizationResult\n\n# Initialize Firestore client (Google Firestore selected as concrete provider)\n# Required environment variable: GOOGLE_APPLICATION_CREDENTIALS\nfirestore_client = firestore.Client()\n\ndef store_expense(record: NormalizationResult) -> dict:\n    \"\"\"Inserts a normalized expense into Firestore and returns the write result.\n\n    Args:\n        record (NormalizationResult): The normalized expense payload.\n\n    Returns:\n        dict: Metadata about the write operation (document ID, timestamps).\n    \"\"\"\n    if not record.success:\n        raise ValueError('Cannot store an unsuccessful normalization')\n    doc_ref = firestore_client.collection('expenses').document()  # auto‑ID\n    # Convert dataclasses to plain dict (strip type info)\n    payload = {\n        'vendor': record.expense.vendor,\n        'date': record.expense.date,\n        'total': record.expense.total,\n        'items': record.expense.items,\n        'created_at': firestore.SERVER_TIMESTAMP,\n        'updated_at': firestore.SERVER_TIMESTAMP,\n    }\n    try:\n        doc_ref.set(payload)\n    except GoogleAuthError as e:\n        raise RuntimeError('Firestore authentication failed') from e\n    return {\n        'document_id': doc_ref.id,\n        'status': 'stored',\n        'metadata': payload\n    }\n\n# Example usage (uncomment to test):\n# norm = NormalizationResult(\n#     expense=NormalizationResult.NormalizedExpense(\n#         vendor='Acme', date='2024-07-15', total=123.45, items=['Widget']),\n#     success=True,\n# )\n# print(store_expense(norm))\n
